function [obs,info] = myReset()
  info = [0;0]; obs = info;
end
function [obs,r,done,info] = myStep(a,info)
  info = info + [info(2); 0.1*a];
  obs = info; r = -sum(info.^2); done = abs(info(1)) > 5;
end

